INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_FOLKLORE','Modern Urban Legend & Folklore (19th–20th c.)',1800,2000),
 ('PER_DIGITAL_FOLKLORE','Digital-Age Folklore & Vernacular Religion (21st c.)',2000,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_HUFFORD_NIGHT','secondary scholarship','David J. Hufford, The Terror That Comes in the Night: An Experience-Centered Study of Supernatural Assault Traditions (1982)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_ADLER_SLEEP','secondary scholarship','Shelley R. Adler, Sleep Paralysis: Night-mares, Nocebos, and the Mind-Body Connection (2011)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_STRASSMAN_DMT','primary text','Rick Strassman, DMT: The Spirit Molecule (2001)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_DAVIS_DMT_ENTITY','secondary scholarship','Davis, Clifton, Weaver, Hurwitz, Johnson & Griffiths, ''Survey of entity encounter experiences occasioned by inhaled N,N-dimethyltryptamine'' (J. Psychopharmacology, 2020)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_PECK_SLENDERMAN','secondary scholarship','Andrew Peck, ''Tall, Dark, and Loathsome: The Emergence of a Legend Cycle in the Digital Age'' (Journal of American Folklore, 2015)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_DUNDES_BLOODYMARY','secondary scholarship','Alan Dundes, ''Bloody Mary in the Mirror: A Ritual Reflection of Pre-Pubescent Anxiety'' (in Bloody Mary in the Mirror, 2002)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_KEEL_MOTHMAN','primary text','John A. Keel, The Mothman Prophecies (1975)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_ELLIS_OSTENSION','secondary scholarship','Bill Ellis, Aliens, Ghosts, and Cults: Legends We Live (2001)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_LUHRMANN_TULPA','secondary scholarship','T. M. Luhrmann & colleagues; and Samuel Veissière, ''Varieties of Tulpa Experiences'' (in Somatosphere / Hg. Studies, 2016)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_YUDKOWSKY_BASILISK','secondary scholarship','David Auerbach, ''The Most Terrifying Thought Experiment of All Time'' (Slate, 2014); LessWrong forum record of Roko''s Basilisk','Contemporary Folklore & Vernacular Religion'),
 ('SRC_RADFORD_CHUPACABRA','secondary scholarship','Benjamin Radford, Tracking the Chupacabra (2011)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_PERLOFF_LLORONA','secondary scholarship','Domino Renee Perez, There Was a Woman: La Llorona from Folklore to Popular Culture (2008)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_RIDENOUR_KRAMPUS','secondary scholarship','Al Ridenour, The Krampus and the Old, Dark Christmas (2016)','Contemporary Folklore & Vernacular Religion')
INSERT INTO _e VALUES
 ('ENT_VF_SLEEP_PARALYSIS_ENTITIES','Sleep-Paralysis Entities','Collective','Sleep-paralysis entity','Contemporary Folklore & Vernacular Religion','nocturnal assault; chest-pressure; intruder presence; paralysis','B','Hub for the recurring figures of the supernatural-assault tradition documented by Hufford and Adler: cross-culturally stable, experience-centered encounters during sleep paralysis that people interpret and ward against (light left on, prayer, sleeping position changes).'),
 ('ENT_VF_HAT_MAN','The Hat Man','Folkloric being','Sleep-paralysis entity','Contemporary Folklore & Vernacular Religion','sleep paralysis; shadow intrusion; dread presence','B','A tall brimmed-hat shadow figure reported by thousands during sleep paralysis. People genuinely engage him apotropaically — refusing eye contact, praying, leaving lights on, repositioning to avoid recurrence. Documented as a recurrent experiential encounter, not authored fiction.'),
 ('ENT_VF_SHADOW_PEOPLE','Shadow People','Folkloric being','Sleep-paralysis entity','Contemporary Folklore & Vernacular Religion','shadow apparition; bedroom intrusion; menacing presence','B','Dark humanoid figures perceived at the bed or in peripheral vision, frequently during sleep paralysis. Experiencers describe protective responses (prayer, invocation of guardian angels, banishing) — a lived apotropaic engagement, not a written character.'),
 ('ENT_VF_OLD_HAG','The Old Hag (Night-Hag)','Folkloric being','Sleep-paralysis entity','Contemporary Folklore & Vernacular Religion','nocturnal pressing; suffocation; ''hagging''; paralysis','B','The Newfoundland ''Old Hag'' who sits on the sleeper''s chest — Hufford''s core case for an experience-centered, cross-cultural assault tradition. People take protective measures (''being hagged'' is acted upon). A genuine continuation of the older mare/night-mare and Lilith-as-strangler complex.'),
 ('ENT_VF_DMT_MACHINE_ELVES','DMT Machine Elves','Spirit','Entheogenic encounter entity','Contemporary Folklore & Vernacular Religion','entheogenic visionary contact; otherworld guides; hyperspace','B','The ''self-transforming machine elves'' (Terence McKenna) / autonomous entities reported by DMT users. People ritually occasion the encounter (set, setting, ceremony) and act on the perceived contact as relational/communicative; Strassman''s clinical study and the Davis/Griffiths survey document the recurrent, agentic experience.'),
 ('ENT_VF_DMT_MANTIS','The Mantis (DMT Entity)','Spirit','Entheogenic encounter entity','Contemporary Folklore & Vernacular Religion','insectoid intelligence; visionary surgery; otherworld examiner','C','A recurrent insectoid/mantis-like entity reported in DMT encounters, often performing ''operations'' on the experiencer. Documented as a distinct recurring entity-type in the Davis et al. survey; people engage it as an autonomous being. C for emergent/contested status.'),
 ('ENT_VF_MODERN_CRYPTIDS','Modern Cryptids','Collective','Cryptid','Contemporary Folklore & Vernacular Religion','sighting waves; omen; rural menace','B','Hub for the venerated/feared cryptids of vernacular belief that people engage as harbingers or threats (not mere believed animals): Mothman, Chupacabra, Jersey Devil.'),
 ('ENT_VF_MOTHMAN','Mothman','Cryptid','Cryptid','Contemporary Folklore & Vernacular Religion','omen; harbinger of disaster; winged apparition','B','Winged red-eyed being of the 1966–67 Point Pleasant sighting wave, treated as a harbinger of the Silver Bridge collapse. Engaged experientially and as an omen/portent (Keel); people interpret sightings as warnings — an apotropaic/divinatory reading, not fiction.'),
 ('ENT_VF_CHUPACABRA','Chupacabra','Cryptid','Cryptid','Contemporary Folklore & Vernacular Religion','livestock predation; blood-draining; rural dread','B','The ''goat-sucker'' blamed for exsanguinated livestock across Latin America and the US Southwest since 1995. Communities act on it (livestock protection, vigilance, reporting) as a real present threat; Radford traces the lived legend.'),
 ('ENT_VF_JERSEY_DEVIL','The Jersey Devil','Cryptid','Cryptid','Contemporary Folklore & Vernacular Religion','Pine Barrens haunting; winged menace; regional omen','B','Winged hooved creature of the New Jersey Pine Barrens, tied to the Mother Leeds birth legend. A durable regional belief people invoke and search for; the 1909 sighting panic shows lived apotropaic engagement (schools closed, people stayed indoors).'),
 ('ENT_VF_APOTROPAIC_BOGEYS','Apotropaic Bogeys','Collective','Apotropaic figure','Contemporary Folklore & Vernacular Religion','child-warding; threshold dread; ''don''t let them in''','B','Hub for the warning-figures invoked to control behavior or guard thresholds — El Cucuy/the Boogeyman and the Black-Eyed Children — engaged through avoidance, refusal, and protective ritual.'),
 ('ENT_VF_EL_CUCUY','El Cucuy (the Boogeyman / Sack Man)','Folkloric being','Apotropaic figure','Contemporary Folklore & Vernacular Religion','child-fear; abduction threat; behavioral warning','B','The bogeyman invoked by caregivers (El Cucuy / Coco / the Sack Man / ''el hombre del saco'') to enforce child behavior — ''he takes children who misbehave.'' A living apotropaic verbal custom with active warding/threat function across Hispanic and broader folk cultures.'),
 ('ENT_VF_BLACK_EYED_CHILDREN','Black-Eyed Children','Folkloric being','Apotropaic figure','Contemporary Folklore & Vernacular Religion','threshold intrusion; permission-seeking menace; ''don''t let them in''','C','Children with all-black eyes who appear at doors/cars asking to be let in; the lived rule is strictly apotropaic — refuse them entry. An ostensive legend people act on (reports of declining to open doors); C for emergent/contested.'),
 ('ENT_VF_LA_LLORONA','La Llorona','Spirit','Apotropaic figure','Contemporary Folklore & Vernacular Religion','weeping ghost; waterside child-warning; drowning omen','B','The Weeping Woman who drowned her children and seeks others by water. Invoked apotropaically to keep children away from rivers/canals after dark; a living warning-spirit with active protective function (Perez documents the lived tradition).'),
 ('ENT_VF_KRAMPUS','Krampus','Folkloric being','Apotropaic figure','Contemporary Folklore & Vernacular Religion','Alpine winter ritual; child-discipline; companion of St. Nicholas','B','Horned Alpine companion of St. Nicholas who punishes bad children. A living ritual custom — Krampusnacht (Dec. 5) Krampuslauf processions of masked runners with switches and bells — performed apotropaically/seasonally across Austria, Bavaria, and beyond.'),
 ('ENT_VF_BLOODY_MARY','Bloody Mary','Spirit','Urban legend','Contemporary Folklore & Vernacular Religion','mirror-summoning; ritual conjuration; adolescent rite','B','A mirror-bound apparition deliberately summoned by chanting her name (often thrice) into a darkened mirror. The summoning ritual is genuinely performed (Dundes analyzes it as a pre-pubescent ostensive rite) — active ritual engagement, not fiction.'),
 ('ENT_VF_ZOZO','Zozo','Spirit','Urban legend','Contemporary Folklore & Vernacular Religion','Ouija-board demon; spirit-board dread; warding','C','A malevolent entity said to manifest on the Ouija board, named when the planchette swings Z-O-Z-O. People engage it ritually (board contact) and apotropaically (refusing to play, closing the board, ''goodbye'' protocols, prayer). C for emergent contested legend.'),
 ('ENT_VF_SLENDER_MAN','Slender Man','Egregore','Online ostensive legend','Contemporary Folklore & Vernacular Religion','abduction; proxies; the Operator; ostensive ritual','B','FLAG: born June 2009 as Something Awful fiction (Eric Knudsen), but crossed into ostensive folklore — circulated summoning rituals, the ''proxies''/Operator mythos, and people acting as though real (the 2014 Waukesha stabbing). Included on the documented lived ritual/ostensive practice (Peck), not the original fiction.'),
 ('ENT_VF_TULPA','Tulpa (Thoughtform)','Thoughtform','Online ostensive legend','Contemporary Folklore & Vernacular Religion','created thoughtform; relational companion; mind-creation practice','B','A consciously created mental companion experienced as semi-autonomous. The r/Tulpas community practices a genuine relational discipline (focused creation, ''forcing'', dialogue) and acts on the tulpa as a present interlocutor — a lived vernacular practice (Veissière''s ''Varieties of Tulpa Experiences'').'),
 ('ENT_VF_ROKOS_BASILISK','Roko''s Basilisk','Egregore','Digital eschatology','Contemporary Folklore & Vernacular Religion','acausal punishment; AI eschatology; dread some act on','C','FLAG: a 2010 LessWrong thought experiment — a future superintelligence that acausally punishes those who knew of it but failed to help it exist. Included as digital eschatology some genuinely act on (reported anxiety, refusal to think about it, the forum''s banning). Engagement is dread/avoidance. C for contested/emergent.');
