INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_VF_HAT_MAN','member_of','ENT_VF_SLEEP_PARALYSIS_ENTITIES','high','The Hat Man is a core recurring figure of the supernatural-assault / sleep-paralysis tradition.'),
 ('ENT_VF_SHADOW_PEOPLE','member_of','ENT_VF_SLEEP_PARALYSIS_ENTITIES','high','Shadow People are a recurring figure of the sleep-paralysis assault tradition.'),
 ('ENT_VF_OLD_HAG','member_of','ENT_VF_SLEEP_PARALYSIS_ENTITIES','high','The Old Hag is Hufford''s paradigm case of the experience-centered sleep-paralysis tradition.'),
 ('ENT_VF_OLD_HAG','reception_of','ENT_JM_LILITH','medium','The chest-pressing night-hag/strangler complex continues the older Lilith-as-nocturnal-strangler / mara night-mare tradition.'),
 ('ENT_VF_OLD_HAG','opposed_by','ENT_CHR_GUARDIAN_ANGELS','medium','Sleep-paralysis experiencers invoke prayer and guardian angels to ward off the pressing Hag.'),
 ('ENT_VF_SHADOW_PEOPLE','opposed_by','ENT_CHR_GUARDIAN_ANGELS','low','Experiencers commonly invoke guardian-angel protection and prayer against Shadow People.'),
 ('ENT_VF_DMT_MANTIS','aligned_with','ENT_VF_DMT_MACHINE_ELVES','high','The Mantis and the machine elves are the two best-documented recurrent DMT entity-types, both encountered in the same entheogenic visionary space.'),
 ('ENT_VF_MOTHMAN','member_of','ENT_VF_MODERN_CRYPTIDS','high','Mothman is a paradigmatic modern cryptid of the sighting-wave tradition.'),
 ('ENT_VF_CHUPACABRA','member_of','ENT_VF_MODERN_CRYPTIDS','high','The Chupacabra is a core modern cryptid of vernacular belief.'),
 ('ENT_VF_JERSEY_DEVIL','member_of','ENT_VF_MODERN_CRYPTIDS','high','The Jersey Devil is a durable regional modern cryptid.'),
 ('ENT_VF_MOTHMAN','embodies','ENT_APOCALYPSE','medium','Mothman is read as a harbinger of catastrophe (the Silver Bridge collapse), embodying disaster-omen / eschatological dread.'),
 ('ENT_VF_EL_CUCUY','member_of','ENT_VF_APOTROPAIC_BOGEYS','high','El Cucuy/the Boogeyman is the archetypal apotropaic child-warding bogey.'),
 ('ENT_VF_BLACK_EYED_CHILDREN','member_of','ENT_VF_APOTROPAIC_BOGEYS','high','The Black-Eyed Children are engaged through the apotropaic ''don''t let them in'' threshold rule.'),
 ('ENT_VF_LA_LLORONA','opposed_by','ENT_CHR_GUARDIAN_ANGELS','low','La Llorona is warded against (prayer, keeping children from water) within a Catholic folk frame invoking angelic/saintly protection.'),
 ('ENT_VF_LA_LLORONA','aligned_with','ENT_VF_APOTROPAIC_BOGEYS','medium','La Llorona functions as an apotropaic child-warning figure alongside the bogey complex.'),
 ('ENT_VF_KRAMPUS','aligned_with','ENT_SAINT_NICHOLAS','high','Krampus is the punishing companion of St. Nicholas in the Alpine Nicholas–Krampus winter custom (Krampusnacht).'),
 ('ENT_VF_KRAMPUS','opposed_by','ENT_SAINT_NICHOLAS','medium','St. Nicholas rewards good children while restraining/pairing with Krampus who punishes the bad — a protector-vs-menace dyad in the living custom.'),
 ('ENT_VF_ZOZO','opposed_by','ENT_CHR_GUARDIAN_ANGELS','low','Ouija practitioners ward off Zozo with prayer, board-closing protocols, and appeals to angelic protection.'),
 ('ENT_VF_BLOODY_MARY','aligned_with','ENT_VF_ZOZO','medium','Bloody Mary and Zozo are both deliberately summoned/contacted entities of adolescent ritual-conjuration legendry.'),
 ('ENT_VF_SLENDER_MAN','aligned_with','ENT_VF_MODERN_CRYPTIDS','low','Slender Man is the leading online-born ostensive being, sharing the sighting/menace mode with the modern cryptid cluster.'),
 ('ENT_VF_TULPA','aligned_with','ENT_VF_DMT_MACHINE_ELVES','low','Tulpas and DMT entities are both relational, agentic mind-encountered beings people engage as autonomous interlocutors.'),
 ('ENT_VF_ROKOS_BASILISK','aligned_with','ENT_VF_SLENDER_MAN','low','Roko''s Basilisk and Slender Man are both digital-age egregores born online that some people genuinely act on (dread/avoidance).');
INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
